406	bool TheoryArith::collectModelValues(TheoryModel* m,
407	                                     const std::set<Node>& termSet)
408	{
409	  if (TraceIsOn("arith::model"))
410	  {
411	    Trace("arith::model") << "arithmetic model after pruning" << std::endl;
412	    for (const auto& p : d_arithModelCache)
413	    {
414	      Trace("arith::model")
415	          << "\t" << p.first << " -> " << p.second << std::endl;
416	    }
417	  }
418	
419	  updateModelCacheInternal(termSet);
420	
421	  // We are now ready to assert the model.
422	  for (const std::pair<const Node, Node>& p : d_arithModelCache)
423	  {
424	    if (termSet.find(p.first) == termSet.end())
425	    {
426	      continue;
427	    }
428	    // do not assert non-leafs e.g. non-linear multiplication terms,
429	    // transcendental functions, etc.
430	    if (!Theory::isLeafOf(p.first, TheoryId::THEORY_ARITH))
431	    {
432	      continue;
433	    }
434	    // maps to constant of same type
435	    AssertEqual(p.first.getType(), p.second.getType())
436	        << "Bad type : " << p.first << " -> " << p.second;
437	    if (m->assertEquality(p.first, p.second, true))
438	    {
439	      continue;
440	    }
441	    else if (d_valuation.needCheck())
442	    {
443	      // If a theory solver has already sent a lemma in this context, we
444	      // know that theory engine will be called to recheck, so we can safely
445	      // return unsuccessfully here. Note that the arithmetic solver itself
446	      // may be the one that sent the lemma, for instance if we had buffered
447	      // lemmas during the call to needsCheckLastEffort.
448	      return false;
449	    }
450	    DebugUnhandled() << "A model equality could not be asserted: " << p.first
451	                     << " == " << p.second << std::endl;
452	    // If we failed to assert an equality, it is likely due to theory
453	    // combination, namely the repaired model for non-linear changed
454	    // an equality status that was agreed upon by both (linear) arithmetic
455	    // and another theory. In this case, we must add a lemma, or otherwise
456	    // we would terminate with an invalid model. Thus, we add a splitting
457	    // lemma of the form ( x = v V x != v ) where v is the model value
458	    // assigned by the non-linear solver to x.
459	    if (d_nonlinearExtension != nullptr)
460	    {
461	      Node eq = p.first.eqNode(p.second);
462	      Node lem = nodeManager()->mkNode(Kind::OR, eq, eq.negate());
463	      bool added = d_im.lemma(lem, InferenceId::ARITH_SPLIT_FOR_NL_MODEL);
464	      AlwaysAssert(added) << "The lemma was already in cache. Probably there "
465	                             "is something wrong with theory combination...";
466	    }
467	    return false;
468	  }
469	  return true;
470	}
