477	{
478	  Trace("arith-eq-status") << "TheoryArith::getEqualityStatus(" << a << ", "
479	                           << b << ")" << std::endl;
480	  if (a == b)
481	  {
482	    Trace("arith-eq-status") << "...return (trivial) true" << std::endl;
483	    return EQUALITY_TRUE_IN_MODEL;
484	  }
485	  if (d_arithModelCache.empty())
486	  {
487	    EqualityStatus es = d_internal.getEqualityStatus(a, b);
488	    Trace("arith-eq-status") << "...return (from linear) " << es << std::endl;
489	    return es;
490	  }
491	  Trace("arith-eq-status") << "Evaluate under " << d_arithModelCacheSubs.d_vars
492	                           << " / " << d_arithModelCacheSubs.d_subs
493	                           << std::endl;
494	  Node diff = nodeManager()->mkNode(Kind::SUB, a, b);
495	  // do not traverse non-linear multiplication here, since the value of
496	  // multiplication in this method should consider the value of the
497	  // non-linear multiplication term, and not its evaluation.
498	  std::optional<bool> isZero =
499	      isExpressionZero(d_env, diff, d_arithModelCacheSubs, false);
500	  if (isZero)
501	  {
502	    EqualityStatus es =
503	        *isZero ? EQUALITY_TRUE_IN_MODEL : EQUALITY_FALSE_IN_MODEL;
504	    Trace("arith-eq-status") << "...return (from evaluate) " << es << std::endl;
505	    return es;
506	  }
507	  Trace("arith-eq-status") << "...return unknown" << std::endl;
508	  return EQUALITY_UNKNOWN;
