566	bool TheoryArith::sanityCheckIntegerModel()
567	{
568	  // Double check that the model from the linear solver respects integer types,
569	  // if it does not, add a branch and bound lemma. This typically should never
570	  // be necessary, but is needed in rare cases.
571	  if (Configuration::isAssertionBuild())
572	  {
573	    for (CVC5_UNUSED const auto& p : d_arithModelCache)
574	    {
575	      AssertEqual(p.first.getType(), p.second.getType())
576	          << "Bad type: " << p.first << " -> " << p.second;
577	    }
578	  }
579	  bool addedLemma = false;
580	  bool badAssignment = false;
581	  Trace("arith-check") << "model:" << std::endl;
582	  for (const auto& p : d_arithModelCacheIllTyped)
583	  {
584	    Trace("arith-check") << p.first << " -> " << p.second << std::endl;
585	    Assert(p.first.getType().isInteger() && !p.second.getType().isInteger());
586	    warning() << "TheoryArithPrivate generated a bad model value for "
587	                 "integer variable "
588	              << p.first << " : " << p.second << std::endl;
589	    // must branch and bound
590	    std::vector<TrustNode> lems =
591	        d_bab.branchIntegerVariable(p.first, p.second.getConst<Rational>());
592	    for (const TrustNode& lem : lems)
593	    {
594	      if (d_im.trustedLemma(lem, InferenceId::ARITH_BB_LEMMA))
595	      {
596	        addedLemma = true;
597	      }
598	    }
599	    badAssignment = true;
600	  }
601	  if (addedLemma)
602	  {
603	    // we had to add a branch and bound lemma since the linear solver assigned
604	    // a non-integer value to an integer variable.
605	    return true;
606	  }
607	  // this would imply that linear arithmetic's model failed to satisfy a branch
608	  // and bound lemma
609	  AlwaysAssert(!badAssignment)
610	      << "Bad assignment from TheoryArithPrivate::collectModelValues, and no "
611	         "branching lemma was sent";
612	  return false;
613	}
