355	void Theory::collectTerms(TNode n,
356	                          std::set<Node>& termSet,
357	                          const std::set<Kind>& irrKinds) const
358	{
359	  std::vector<TNode> visit;
360	  TNode cur;
361	  visit.push_back(n);
362	  do
363	  {
364	    cur = visit.back();
365	    visit.pop_back();
366	    if (termSet.find(cur) != termSet.end())
367	    {
368	      // already visited
369	      continue;
370	    }
371	    Kind k = cur.getKind();
372	    // only add to term set if a relevant kind
373	    if (irrKinds.find(k) == irrKinds.end())
374	    {
375	      termSet.insert(cur);
376	    }
377	    // traverse owned terms, don't go under quantifiers
378	    if ((k == Kind::NOT || k == Kind::EQUAL || d_env.theoryOf(cur) == d_id)
379	        && !cur.isClosure())
380	    {
381	      visit.insert(visit.end(), cur.begin(), cur.end());
382	    }
383	  } while (!visit.empty());
