287	void LiaStarExtension::getAssertions(std::vector<Node>& assertions)
288	{
289	  // Collect the STAR_CONTAINS atoms among the arithmetic facts. Both polarities
290	  // are reduced to the positive atom: a negated `(not (star-contains ...))` is
291	  // handled by the same reduction lemma `literal = star` (the surrounding SAT
292	  // solver applies the negation).
293	  Trace("liastar-ext") << "Getting assertions..." << std::endl;
294	  Trace("liastar-ext") << "---------------------" << std::endl;
295	  for (auto it = d_arith.facts_begin(); it != d_arith.facts_end(); ++it)
296	  {
297	    Node lit = (*it).d_assertion;
298	    Trace("liastar-ext") << lit << std::endl;
299	    if (lit.getKind() == Kind::STAR_CONTAINS)
300	    {
301	      // positive polarity of star-contains
302	      assertions.push_back(lit);
303	    }
304	    if (lit.getKind() == Kind::NOT && lit[0].getKind() == Kind::STAR_CONTAINS)
305	    {
306	      // negative polarity of star-contains
307	      assertions.push_back(lit[0]);
308	    }
309	  }
310	  Trace("liastar-ext") << "---------------------" << std::endl;
311	}
