313	void LiaStarExtension::checkFullEffort(std::map<Node, Node>& arithModel,
314	                                       const std::set<Node>& termSet)
315	{
316	  // Last-call effort check: for each STAR_CONTAINS assertion emit the necessary
317	  // lemmas and, if the current model does not already satisfy the literal,
318	  // refine via the eager or lazy star reduction.
319	  Trace("liastar-ext") << "interceptModel: do model-based refinement"
320	                       << std::endl;
321	  Trace("liastar-ext") << " model is : " << arithModel << std::endl;
322	  Trace("liastar-ext") << " termSet is: " << termSet << std::endl;
323	  d_checkCounter++;
324	
325	  // get the assertions
326	  std::vector<Node> assertions;
327	  getAssertions(assertions);
328	
329	  Trace("liastar-ext") << "liastar assertions: " << assertions << std::endl;
330	  NodeManager* nm = nodeManager();
331	  for (const auto& literal : assertions)
332	  {
333	    Node lambda = literal[0];
334	    Assert(literal.getKind() == Kind::STAR_CONTAINS);
335	    // vectorPredicate = p[v] (v satisfies p) and nonnegative = (and (>= v_i 0)).
336	    auto [vectorPredicate, nonnegative] =
337	        LiaStarUtils::getVectorPredicate(literal, nm);
338	
339	    // (1) Membership in S* requires v to be in the non-negative orthant.
340	    if (d_proofGen != nullptr)
341	    {
342	      d_proofGen->registerNonnegative(nonnegative, literal);
343	    }
344	    d_im.addPendingLemma(
345	        nonnegative, InferenceId::ARITH_LIA_STAR_NONNEGATIVE, d_proofGen.get());
346	
347	    // (2) Split on whether v itself satisfies p: if so, v is a single-summand
348	    // member of S* and the literal holds directly.
349	    Node split = vectorPredicate.orNode(vectorPredicate.notNode());
350	    if (d_proofGen != nullptr)
351	    {
352	      d_proofGen->registerSplit(split, vectorPredicate);
353	    }
354	    d_im.addPendingLemma(
355	        split, InferenceId::ARITH_LIA_STAR_SPLIT, d_proofGen.get());
356	    d_im.doPendingLemmas();
357	    if (d_im.hasSentLemma())
358	    {
359	      Trace("liastar-ext") << "Sending lemma: " << split << std::endl;
360	      continue;
361	    }
362	    if (options().arith.arithLiaStarModelValue)
363	    {
364	      // Model-value shortcut: if the current arithmetic model already satisfies
365	      // the predicate p[v] (or the last computed star under-approximation),
366	      // then the literal holds in this model and no further refinement is
367	      // needed this round.
368	      std::vector<Node> keys;
369	      std::vector<Node> values;
370	
371	      for (const auto& [key, value] : arithModel)
372	      {
373	        keys.push_back(key);
374	        values.push_back(value);
375	      }
376	
377	      // F: the membership predicate. Additionally consider the last computed
378	      // starLia under-approximation, if any: if the model already satisfies
379	      // F or that under-approximation, the literal already holds and no further
380	      // refinement is needed.
381	      Node f = vectorPredicate;
382	      auto starIt = d_lastStarLia.find(literal);
383	      Node check = starIt != d_lastStarLia.end() ? f.orNode(starIt->second) : f;
384	
385	      Node value = check.substitute(
386	          keys.begin(), keys.end(), values.begin(), values.end());
387	      value = rewrite(value);
388	
389	      Trace("liastar-ext-debug") << "value: " << value << std::endl;
390	
391	      if (value == d_true)
392	      {
393	        Trace("liastar-ext-debug")
394	            << "----------------------------------------" << std::endl;
395	        Trace("liastar-ext-debug")
396	            << literal << " is satisfied in the current model" << std::endl;
397	        Trace("liastar-ext-debug")
398	            << "----------------------------------------" << std::endl;
399	        return;
400	      }
401	    }
402	    // (3) Refine: reduce the star literal to its cone/Hilbert-basis encoding.
403	    if (options().arith.arithLiaStarLazy)
404	    {
405	      lazyCheckStar(literal, lambda);
406	    }
407	    else
408	    {
409	      eagerCheckStar(literal, lambda);
410	    }
411	  }
412	}
